import glob, itertools, sys
files = sorted(glob.glob("*.py"))
def norm(path, drop_comments):
    out=[]
    for i,line in enumerate(open(path).read().splitlines(),1):
        s=line.strip()
        if not s: continue
        if drop_comments and s.startswith("#"): continue
        out.append((i,s))
    return out
def runs(a,b):
    res=[]
    n,m=len(a),len(b)
    dp=[[0]*(m+1) for _ in range(n+1)]
    for i in range(n-1,-1,-1):
        for j in range(m-1,-1,-1):
            if a[i][1]==b[j][1]: dp[i][j]=dp[i+1][j+1]+1
    # maximal runs: start where previous unequal
    for i in range(n):
        for j in range(m):
            L=dp[i][j]
            if L>=5 and (i==0 or j==0 or a[i-1][1]!=b[j-1][1]):
                res.append((L,a[i][0],a[i+L-1][0],b[j][0],b[j+L-1][0]))
    return res
for drop in (False,True):
    print("=== normalization: %s ===" % ("drop comment-only lines" if drop else "comments kept as text, blank lines ignored"))
    data={f:norm(f,drop) for f in files}
    found=0
    for x,y in itertools.combinations(files,2):
        for L,s1,e1,s2,e2 in runs(data[x],data[y]):
            found+=1
            print("%-14s %2d-%-2d  %-14s %2d-%-2d  len=%d" % (x,s1,e1,y,s2,e2,L))
    print("total maximal blocks:", found)
